# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void cross_entropy_kernel(
    const half* predictions,
    const int* targets,
    half* output,
    int batch_size,
    int num_classes
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= batch_size) return;

    // Get the target class for this sample
    int target_class = targets[idx];

    // Find maximum value for numerical stability
    half max_val = predictions[idx * num_classes + 0];
    for (int i = 1; i < num_classes; i++) {
        max_val = fmaxf(__half2float(max_val), __half2float(predictions[idx * num_classes + i])) > __half2float(max_val) ? 
                  predictions[idx * num_classes + i] : max_val;
    }

    // Compute sum of exponentials
    float sum_exp = 0.0f;
    for (int i = 0; i < num_classes; i++) {
        sum_exp += expf(__half2float(predictions[idx * num_classes + i]) - __half2float(max_val));
    }

    // Compute log(sum_exp)
    float log_sum_exp = logf(sum_exp);

    // Compute negative log probability of target class
    float target_log_prob = __half2float(predictions[idx * num_classes + target_class]) - __half2float(max_val) - log_sum_exp;

    // Store result (negative log probability)
    output[idx] = __float2half(-target_log_prob);
}

// Wrapper function to launch kernel
extern "C" void launch_cross_entropy(
    const half* predictions,
    const int* targets,
    half* output,
    int batch_size,
    int num_classes
) {
    int block_size = 256;
    int grid_size = (batch_size + block_size - 1) / block_size;

    cross_entropy_kernel<<<grid_size, block_size>>>(
        predictions, targets, output, batch_size, num_classes
    );

    cudaDeviceSynchronize();
}
"""

